/**
 * Media Viewer Styles - 图片放大 & 自定义视频播放器样式
 * 适用于 ciallo0721-cmd.github.io 文章页面
 */

/* ==================== 图片相关样式 ==================== */

.article-image-container {
    text-align: center;
    margin: 30px 0;
}

.article-img,
.zoomable {
    max-width: 100%;
    height: auto;
    border-radius: 16px;
    box-shadow: 0 6px 20px rgba(0, 0, 0, 0.1);
    display: block;
    margin: 0 auto;
    cursor: zoom-in;
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.article-img:hover,
.zoomable:hover {
    transform: translateY(-3px);
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.15);
}

.image-caption {
    text-align: center;
    font-size: 0.9rem;
    color: #515154;
    margin-top: 15px;
    margin-bottom: 25px;
    font-style: italic;
}

/* 图片放大弹窗 */
.image-zoom-modal {
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.92);
    display: none;
    justify-content: center;
    align-items: center;
    z-index: 10000;
    cursor: zoom-out;
    animation: fadeIn 0.3s ease;
}

.image-zoom-modal.active {
    display: flex;
}

.image-zoom-modal img {
    max-width: 90%;
    max-height: 90%;
    border-radius: 12px;
    box-shadow: 0 20px 60px rgba(0, 0, 0, 0.5);
    animation: zoomIn 0.3s ease;
}

.image-zoom-close {
    position: absolute;
    top: 20px;
    right: 30px;
    color: white;
    font-size: 2.5rem;
    cursor: pointer;
    opacity: 0.8;
    transition: opacity 0.3s;
    line-height: 1;
}

.image-zoom-close:hover {
    opacity: 1;
}

@keyframes fadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

@keyframes zoomIn {
    from { transform: scale(0.8); opacity: 0; }
    to { transform: scale(1); opacity: 1; }
}

/* ==================== 视频播放器样式 ==================== */

.article-video-container {
    margin: 40px 0;
    text-align: center;
}

/* 自定义视频播放器 */
.custom-video-player {
    position: relative;
    width: 100%;
    max-width: 800px;
    margin: 0 auto;
    border-radius: 20px;
    overflow: hidden;
    background: linear-gradient(135deg, #1a1a2e, #16213e);
    box-shadow: 0 10px 40px rgba(0, 0, 0, 0.3);
}

.custom-video-player video {
    width: 100%;
    height: auto;
    display: block;
    border-radius: 20px;
}

.video-poster {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    cursor: pointer;
    z-index: 2;
    display: flex;
    align-items: center;
    justify-content: center;
}

.video-poster img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    border-radius: 20px;
}

.play-button {
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 80px;
    height: 80px;
    background: linear-gradient(135deg, #FB7299, #00A1D6);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: 0 8px 30px rgba(251, 114, 153, 0.5);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
}

.play-button:hover {
    transform: translate(-50%, -50%) scale(1.1);
    box-shadow: 0 12px 40px rgba(251, 114, 153, 0.6);
}

.play-button i {
    color: white;
    font-size: 2rem;
    margin-left: 5px;
}

.video-controls {
    position: absolute;
    bottom: 0;
    left: 0;
    right: 0;
    background: linear-gradient(to top, rgba(0,0,0,0.8), transparent);
    padding: 20px 15px 15px;
    display: flex;
    align-items: center;
    gap: 12px;
    opacity: 0;
    transition: opacity 0.3s ease;
    z-index: 3;
}

.custom-video-player:hover .video-controls,
.custom-video-player.playing .video-controls {
    opacity: 1;
}

.control-btn {
    background: none;
    border: none;
    color: white;
    font-size: 1rem;
    cursor: pointer;
    padding: 8px;
    border-radius: 8px;
    transition: background 0.2s;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    flex-shrink: 0;
}

.control-btn:hover {
    background: rgba(255, 255, 255, 0.2);
}

.progress-container {
    flex: 1;
    height: 20px;
    display: flex;
    align-items: center;
    cursor: pointer;
}

.progress-bar {
    width: 100%;
    height: 6px;
    background: rgba(255, 255, 255, 0.3);
    border-radius: 3px;
    position: relative;
    overflow: visible;
}

.progress-fill {
    height: 100%;
    background: linear-gradient(135deg, #FB7299, #00A1D6);
    border-radius: 3px;
    width: 0%;
    transition: width 0.1s linear;
}

.progress-handle {
    position: absolute;
    top: 50%;
    left: 0%;
    transform: translate(-50%, -50%);
    width: 14px;
    height: 14px;
    background: white;
    border-radius: 50%;
    box-shadow: 0 2px 8px rgba(0,0,0,0.3);
    opacity: 0;
    transition: opacity 0.2s, transform 0.2s;
}

.progress-container:hover .progress-handle {
    opacity: 1;
}

.time-display {
    color: white;
    font-size: 0.85rem;
    font-family: 'MaokenAssortedSans', 'Monaco', 'Menlo', 'Ubuntu Mono', monospace;
    min-width: 100px;
    text-align: center;
    flex-shrink: 0;
}

.volume-slider {
    width: 80px;
    height: 6px;
    background: rgba(255, 255, 255, 0.3);
    border-radius: 3px;
    cursor: pointer;
    position: relative;
    flex-shrink: 0;
}

.volume-fill {
    height: 100%;
    background: white;
    border-radius: 3px;
    width: 70%;
}

.custom-video-player.playing .video-poster {
    display: none;
}

/* 响应式适配 */
@media (max-width: 768px) {
    .custom-video-player {
        border-radius: 12px;
    }

    .custom-video-player video {
        border-radius: 12px;
    }

    .video-poster img {
        border-radius: 12px;
    }

    .play-button {
        width: 60px;
        height: 60px;
    }

    .play-button i {
        font-size: 1.5rem;
    }

    .video-controls {
        padding: 15px 10px 10px;
        gap: 8px;
    }

    .control-btn {
        width: 32px;
        height: 32px;
        padding: 6px;
    }

    .time-display {
        font-size: 0.75rem;
        min-width: 80px;
    }

    .volume-slider {
        width: 50px;
    }
}

@media (max-width: 480px) {
    .video-controls {
        flex-wrap: wrap;
    }

    .progress-container {
        order: -1;
        width: 100%;
        flex: none;
    }

    .volume-slider {
        display: none;
    }
}

/* 断网提示覆盖层 */
.mv-network-disconnected {
    display: none;
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: rgba(0, 0, 0, 0.75);
    color: #fff;
    align-items: center;
    justify-content: center;
    z-index: 20;
    font-size: 1rem;
    flex-direction: column;
    gap: 10px;
    pointer-events: none;
}

.mv-network-disconnected i {
    font-size: 2.5rem;
    color: #f59e0b;
    margin-bottom: 4px;
}

/**
 * Media Viewer - 图片放大 & 自定义视频播放器
 * 适用于 ciallo0721-cmd.github.io 文章页面
 * 
 * 使用方法：
 * 1. 在 HTML 中引入此脚本：<script src="../../media-viewer.js"></script>
 * 2. 图片添加 class="zoomable" 即可点击放大
 * 3. 视频使用自定义播放器结构（见下方示例）
 */

(function() {
    'use strict';

    // ==================== 图片放大功能 ====================

    function initImageZoom() {
        // 如果已存在弹窗，不再创建
        if (document.getElementById('imageZoomModal')) return;

        // 创建放大弹窗
        const modal = document.createElement('div');
        modal.id = 'imageZoomModal';
        modal.className = 'image-zoom-modal';
        modal.innerHTML = `
            <span class="image-zoom-close">&times;</span>
            <img src="" alt="放大图片" id="zoomedImage">
        `;
        document.body.appendChild(modal);

        const modalImg = modal.querySelector('#zoomedImage');
        const closeBtn = modal.querySelector('.image-zoom-close');

        // 为所有可放大的图片添加点击事件
        document.querySelectorAll('.zoomable').forEach(img => {
            img.addEventListener('click', function() {
                modalImg.src = this.src;
                modalImg.alt = this.alt;
                modal.classList.add('active');
                document.body.style.overflow = 'hidden';
            });
        });

        // 关闭弹窗
        function closeModal() {
            modal.classList.remove('active');
            document.body.style.overflow = '';
        }

        closeBtn.addEventListener('click', closeModal);
        modal.addEventListener('click', function(e) {
            if (e.target === modal) closeModal();
        });

        // ESC键关闭
        document.addEventListener('keydown', function(e) {
            if (e.key === 'Escape' && modal.classList.contains('active')) {
                closeModal();
            }
        });
    }

    // ==================== 自定义视频播放器 ====================

    function initCustomVideoPlayer() {
        document.querySelectorAll('.custom-video-player').forEach(player => {
            // 避免重复初始化
            if (player.dataset.initialized === 'true') return;
            player.dataset.initialized = 'true';

            const videoSrc = player.dataset.src;
            const posterSrc = player.dataset.poster;
            const video = player.querySelector('.video-element');
            const poster = player.querySelector('.video-poster');
            const playBtn = player.querySelector('.play-button');
            const playPauseBtn = player.querySelector('.play-pause');
            const progressBar = player.querySelector('.progress-bar');
            const progressFill = player.querySelector('.progress-fill');
            const progressHandle = player.querySelector('.progress-handle');
            const timeDisplay = player.querySelector('.time-display');
            const volumeBtn = player.querySelector('.volume');
            const volumeSlider = player.querySelector('.volume-slider');
            const volumeFill = player.querySelector('.volume-fill');
            const fullscreenBtn = player.querySelector('.fullscreen');

            if (!video || !videoSrc) return;

            // 设置视频源
            video.src = videoSrc;
            if (posterSrc) video.poster = posterSrc;

            let isDragging = false;

            // 播放/暂停
            function togglePlay() {
                if (video.paused) {
                    var p = video.play();
                    if (p !== undefined) {
                        p.catch(function(err) {
                            // AbortError 由用户主动暂停引起，静默忽略
                            if (err.name === 'AbortError') return;
                            console.error('[MediaViewer] 播放失败:', err);
                        });
                    }
                    player.classList.add('playing');
                    if (playPauseBtn) playPauseBtn.innerHTML = '<i class="fas fa-pause"></i>';
                } else {
                    video.pause();
                    player.classList.remove('playing');
                    if (playPauseBtn) playPauseBtn.innerHTML = '<i class="fas fa-play"></i>';
                }
            }

            if (playBtn) playBtn.addEventListener('click', togglePlay);
            if (playPauseBtn) playPauseBtn.addEventListener('click', togglePlay);
            video.addEventListener('click', togglePlay);

            // 更新进度
            video.addEventListener('timeupdate', function() {
                if (!isDragging && progressFill && progressHandle) {
                    const percent = (video.currentTime / video.duration) * 100;
                    progressFill.style.width = percent + '%';
                    progressHandle.style.left = percent + '%';
                }
                if (timeDisplay) {
                    timeDisplay.textContent = formatTime(video.currentTime) + ' / ' + formatTime(video.duration || 0);
                }
            });

            // 格式化时间
            function formatTime(seconds) {
                if (isNaN(seconds)) return '00:00';
                const mins = Math.floor(seconds / 60);
                const secs = Math.floor(seconds % 60);
                return String(mins).padStart(2, '0') + ':' + String(secs).padStart(2, '0');
            }

            // 进度条点击
            if (progressBar) {
                progressBar.addEventListener('click', function(e) {
                    const rect = progressBar.getBoundingClientRect();
                    const percent = (e.clientX - rect.left) / rect.width;
                    video.currentTime = percent * video.duration;
                });
            }

            // 进度条拖动
            if (progressHandle) {
                progressHandle.addEventListener('mousedown', function(e) {
                    isDragging = true;
                    document.body.style.userSelect = 'none';
                });
            }

            document.addEventListener('mousemove', function(e) {
                if (!isDragging || !progressBar || !progressFill || !progressHandle) return;
                const rect = progressBar.getBoundingClientRect();
                let percent = (e.clientX - rect.left) / rect.width;
                percent = Math.max(0, Math.min(1, percent));
                progressFill.style.width = (percent * 100) + '%';
                progressHandle.style.left = (percent * 100) + '%';
            });

            document.addEventListener('mouseup', function(e) {
                if (isDragging && progressBar) {
                    const rect = progressBar.getBoundingClientRect();
                    let percent = (e.clientX - rect.left) / rect.width;
                    percent = Math.max(0, Math.min(1, percent));
                    video.currentTime = percent * video.duration;
                    isDragging = false;
                    document.body.style.userSelect = '';
                }
            });

            // 音量控制
            let isMuted = false;
            let lastVolume = 0.7;

            if (volumeBtn) {
                volumeBtn.addEventListener('click', function() {
                    if (isMuted) {
                        video.volume = lastVolume;
                        if (volumeFill) volumeFill.style.width = (lastVolume * 100) + '%';
                        volumeBtn.innerHTML = '<i class="fas fa-volume-up"></i>';
                        isMuted = false;
                    } else {
                        lastVolume = video.volume || 0.7;
                        video.volume = 0;
                        if (volumeFill) volumeFill.style.width = '0%';
                        volumeBtn.innerHTML = '<i class="fas fa-volume-mute"></i>';
                        isMuted = true;
                    }
                });
            }

            if (volumeSlider) {
                volumeSlider.addEventListener('click', function(e) {
                    const rect = volumeSlider.getBoundingClientRect();
                    const percent = (e.clientX - rect.left) / rect.width;
                    video.volume = Math.max(0, Math.min(1, percent));
                    if (volumeFill) volumeFill.style.width = (video.volume * 100) + '%';
                    isMuted = video.volume === 0;
                    if (volumeBtn) {
                        volumeBtn.innerHTML = isMuted ? '<i class="fas fa-volume-mute"></i>' : '<i class="fas fa-volume-up"></i>';
                    }
                });
            }

            // 全屏
            if (fullscreenBtn) {
                fullscreenBtn.addEventListener('click', function() {
                    if (document.fullscreenElement) {
                        document.exitFullscreen();
                    } else {
                        player.requestFullscreen();
                    }
                });
            }

            // 视频结束
            video.addEventListener('ended', function() {
                player.classList.remove('playing');
                if (playPauseBtn) playPauseBtn.innerHTML = '<i class="fas fa-play"></i>';
                if (poster) poster.style.display = 'flex';
            });

            // 网络状态监听、断网提示与自动恢复
            (function() {
                var retryCount = 0;
                var maxRetries = 3;
                var baseDelay = 1000;
                var maxDelay = 30000;
                var retryTimer = null;
                var isDisconnected = false;

                var netOverlay = player.querySelector('.mv-network-disconnected');
                if (!netOverlay) {
                    netOverlay = document.createElement('div');
                    netOverlay.className = 'mv-network-disconnected';
                    netOverlay.innerHTML = '<i class="fas fa-wifi-slash"></i> 网络已断开，请检查连接';
                    player.appendChild(netOverlay);
                }

                function showDisconnected() {
                    isDisconnected = true;
                    netOverlay.style.display = 'flex';
                    video.pause();
                }

                function hideDisconnected() {
                    isDisconnected = false;
                    netOverlay.style.display = 'none';
                    retryCount = 0;
                }

                window.addEventListener('online', function() {
                    if (isDisconnected) {
                        console.log('[MediaViewer] 网络已恢复，重新加载视频');
                        hideDisconnected();
                        video.load();
                        video.play().catch(function(){});
                    }
                });

                window.addEventListener('offline', function() {
                    if (!navigator.onLine) {
                        showDisconnected();
                    }
                });

                video.addEventListener('error', function() {
                    if (!navigator.onLine) {
                        showDisconnected();
                        return;
                    }
                    var mediaError = video.error;
                    var isNetworkError = mediaError && (
                        mediaError.code === MediaError.MEDIA_ERR_NETWORK ||
                        (mediaError.message && mediaError.message.indexOf('Network') >= 0) ||
                        (mediaError.message && mediaError.message.indexOf('ERR_INTERNET_DISCONNECTED') >= 0)
                    );
                    if (isNetworkError) {
                        if (retryCount < maxRetries) {
                            var delay = Math.min(baseDelay * Math.pow(2, retryCount), maxDelay);
                            retryCount++;
                            console.log('[MediaViewer] 网络错误，第 ' + retryCount + '/' + maxRetries + ' 次重试，等待 ' + delay + 'ms');
                            clearTimeout(retryTimer);
                            retryTimer = setTimeout(function() { video.load(); }, delay);
                        } else {
                            console.error('[MediaViewer] 重试次数已达上限');
                            retryCount = 0;
                            var evt = new CustomEvent('playererror', {
                                detail: { type: 'network', message: '视频加载失败，请稍后重试' }
                            });
                            player.dispatchEvent(evt);
                        }
                    }
                });
            })();

            // 初始化音量
            video.volume = 0.7;
        });
    }

    // ==================== 自动初始化 ====================

    function init() {
        initImageZoom();
        initCustomVideoPlayer();
    }

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }

    // 暴露到全局，方便手动调用
    window.MediaViewer = {
        initImageZoom: initImageZoom,
        initCustomVideoPlayer: initCustomVideoPlayer,
        init: init
    };
})();

/**
 * 视频播放器 HTML 结构示例：
 * 
 * <div class="article-video-container">
 *     <div class="custom-video-player" data-src="videos/demo.mp4" data-poster="images/poster.jpg">
 *         <div class="video-poster">
 *             <img src="images/poster.jpg" alt="视频封面">
 *             <div class="play-button">
 *                 <i class="fas fa-play"></i>
 *             </div>
 *         </div>
 *         <video class="video-element" preload="metadata"></video>
 *         <div class="video-controls">
 *             <button class="control-btn play-pause"><i class="fas fa-play"></i></button>
 *             <div class="progress-container">
 *                 <div class="progress-bar">
 *                     <div class="progress-fill"></div>
 *                     <div class="progress-handle"></div>
 *                 </div>
 *             </div>
 *             <span class="time-display">00:00 / 00:00</span>
 *             <button class="control-btn volume"><i class="fas fa-volume-up"></i></button>
 *             <div class="volume-slider"><div class="volume-fill"></div></div>
 *             <button class="control-btn fullscreen"><i class="fas fa-expand"></i></button>
 *         </div>
 *     </div>
 *     <div class="image-caption">视频标题</div>
 * </div>
 */
